class Data(bytes):
    def __bytes__(self): raise AssertionError('bytes conversion')
    def __iter__(self): raise AssertionError('iteration')
    def __len__(self): raise AssertionError('length')
class Text(str):
    def __str__(self): raise AssertionError('str conversion')
    def __iter__(self): raise AssertionError('iteration')
    def __len__(self): raise AssertionError('length')
assert a2b_qp(Data(b'A=42_'), True) == b'AB '
assert a2b_qp(Text('A=42_'), True) == b'AB '
assert b2a_qp(Data(b'A B_'), True, True, True) == b'A=20B=5F'
events = []
class Flag:
    def __init__(self, name): self.name = name
    def __bool__(self):
        events.append(self.name)
        return True
assert b2a_qp(data=b'A B_', header=Flag('header'), istext=Flag('istext'), quotetabs=Flag('quotetabs')) == b'A=20B=5F'
assert events == ['quotetabs', 'istext', 'header']

events = []
failure = ValueError('flag failure')
class Flag:
    def __bool__(self):
        events.append('truth')
        raise failure
for function in (a2b_qp, b2a_qp):
    try: function(b'', header=Flag())
    except ValueError as error: assert error is failure
    else: raise AssertionError('failure swallowed')
assert events == ['truth','truth']
events.clear()
try: a2b_qp('é', header=Flag())
except ValueError as error: assert str(error) == 'string argument should contain only ASCII characters'
else: raise AssertionError('non ASCII accepted')
assert events == []
class Length:
    def __len__(self): return 1
assert a2b_qp(b'_', Length()) == b' '
class Invalid:
    def __bool__(self): return 1
try: b2a_qp(b'', Invalid())
except TypeError as error: assert str(error) == '__bool__ should return bool, returned int'
else: raise AssertionError('invalid bool accepted')

events=[]
class Key(str):
    def __hash__(self): return str.__hash__(self)
    def __eq__(self,other):
        events.append(other)
        return str.__eq__(self,other)
    def __str__(self):
        events.append('str')
        return 'rendered'
assert b2a_qp(**{Key('data'):b'_',Key('header'):True}) == b'=5F'
assert events == []
try: b2a_qp(b'',**{Key('wrong'):False})
except TypeError as error: assert error.args == ("b2a_qp() got an unexpected keyword argument 'rendered'",)
else: assert False
assert events == ['data','quotetabs','istext','header','str']
events.clear()
try: a2b_qp(**{Key('wrong'):False})
except TypeError as error: assert error.args == ("a2b_qp() missing required argument 'data' (pos 1)",)
else: assert False
assert events == []

